 test("unsupported_profile_unknown_without_reads",[]{auto m=GateMemory();const auto j=Monstey_WorldHkaiActivationSnapshot(m,NR,NS,"unknown",Extent());Status(j,"UNKNOWN");Check(m.calls==0);auto in=Owned();in.image_sha256="6B8DB778135C082C934463B6524E6B220478F B6987F082AB37CA48A870ACB455";Status(Gate(in),"UNKNOWN");});
 test("native_pending_ready_and_queue_bytes",[]{auto in=Owned();in.row->value_50=UINT64_MAX;Status(Gate(in),"BLOCKED");in.row->value_49=255;Status(Gate(in),"GATE_PASS");in.row->value_48=2;Status(Gate(in),"BLOCKED");in.row->value_50=0;in.row->value_49=0;in.row->value_48=0;Status(Gate(in),"GATE_PASS");});
