 test("missing_observations_remain_unknown",[]{Monstey_HkaiActivationInput in;in.image_sha256=Profile;Status(Gate(in),"UNKNOWN");in=Owned();in.row->identity_3c.reset();Status(Gate(in),"UNKNOWN");in=Owned();in.resource.reset();Status(Gate(in),"UNKNOWN");in=Owned();in.resource->count_80.reset();Status(Gate(in),"UNKNOWN");in=Owned();in.row->key_30.reset();Status(Gate(in),"UNKNOWN");in=Owned();in.row->value_64.reset();Status(Gate(in),"UNKNOWN");});
