 test("caller_extent_missing_equal_end_and_mismatch",[]{auto in=Owned();in.string_extent={};Status(Gate(in),"UNKNOWN");in=Owned();in.string_extent.slots=1;Status(Gate(in),"UNKNOWN");in=Owned();in.string_extent.begin+=8;Status(Gate(in),"UNKNOWN");});
 test("null_and_tagged_pointer_only_lowbit_is_removed",[]{auto in=Owned();in.names[1].tagged_pointer=1;Status(Gate(in),"BLOCKED");in=Owned();in.names[1].tagged_pointer=NN|2;in.names[1].bytes=B{'c','t','i','o','n',0};Status(Gate(in),"BLOCKED");in=Owned();const auto j=Gate(in);Status(j,"GATE_PASS");Check(j["untagged_string_pointer"].as_string()==Monstey_Hex(NN,16));});
 test("byte_comparison_nonUTF8_case_NUL_and_prefix",[]{auto in=Owned();in.row->name_at_10=B{255,254,0};in.names[1].bytes=B{255,254,0};Status(Gate(in),"GATE_PASS");in.row->name_at_10=B{'S',0};in.names[1].bytes=B{'s',0};Status(Gate(in),"BLOCKED");in.row->name_at_10=B{'x',0,1};in.names[1].bytes=B{'x',0,2};Status(Gate(in),"GATE_PASS");in.row->name_at_10=B{'x'};in.names[1].bytes=B{'x'};Status(Gate(in),"UNKNOWN");in.names[1].bytes=B{'y'};Status(Gate(in),"BLOCKED");});
