 test("U32_max_count_is_logarithmic_sparse_unknown",[]{auto in=Owned();in.resource->count_80=UINT32_MAX;in.entries.clear();const auto j=Gate(in);Status(j,"UNKNOWN");Check(j["required_table_index"].as_uint()==2147483647&&j["visited_indices"].size()==1);});
