 test("visited_midpoint_range_and_late_source_flag_range",[]{auto in=Owned();in.resource->table_78=0x00007ffffffffff0ULL;in.entries[0].hash_1c=0x80000000u;in.entries[0].index_18=0;in.entries[1].index_18=0;in.names[0]=in.names[1];const auto j=Gate(in);Status(j,"UNKNOWN");Check(j["reason"].as_string()=="invalid_table_row_address"&&j["visited_indices"]==J::array({1}));in=Owned();in.row->address=0x00007fffffffffa0ULL;Status(Gate(in),"UNKNOWN");});
 test("zero_optional_resource_and_extent_are_lazy",[]{Memory blocked;auto&a=blocked.Make(NR+0x50,8);Monstey_PutU64(a,0,1);blocked.Make(NR+0x49,1);const auto j=Monstey_WorldHkaiActivationSnapshot(blocked,NR,0,Profile,{});Status(j,"BLOCKED");Check(blocked.hits[0x18]==0);auto later=GateMemory();const auto k=Monstey_WorldHkaiActivationSnapshot(later,NR,0,Profile,{});Status(k,"UNKNOWN");Check(k["call_gate_pass"].is_null()&&Has(k,"invalid_user_range"));auto empty=GateMemory();Monstey_PutU32(empty.regions[NS],0x80,0);Status(Monstey_WorldHkaiActivationSnapshot(empty,NR,NS,Profile,{}),"BLOCKED");});
