 test("snapshot_early_name_mismatch_avoids_tail_and_flag",[]{auto m=GateMemory();m.regions[NN]=B{'x'};const auto j=Shot(m);Status(j,"BLOCKED");Check(m.hits[NN+1]==0&&m.hits[NR+0x11]==0&&m.hits[NR+0x64]==0);});
