 Monstey_WriteNewText(argv[1],J::object({{"schema","Monstey.HkaiActivationNativeTests/1"},{"status","PASS"},{"count",static_cast<A>(tests.size())},{"groups",tests},{"original_calls",false},{"runtime_verified",false}}).dump(2)+"\n");std::cout<<"PASS "<<tests.size()<<" activation groups\n";return 0;
